import{c as i,$ as t,Q as p,j as d,g as a,n as c,o as s,m as n}from"./chunks/framework.CWBTDBPu.js";const E=JSON.parse('{"title":"YuTeleport 常见问题","description":"","frontmatter":{"title":"YuTeleport 常见问题"},"headers":[],"relativePath":"plugins/items/yu-teleport/faq.md","filePath":"plugins/items/yu-teleport/faq.md"}'),r={name:"plugins/items/yu-teleport/faq.md"},h={class:"quick-actions"};function u(k,e,b,y,g,m){const o=t("CopyMarkdownButton"),l=t("CopyLLMButton");return p(),d("div",null,[e[0]||(e[0]=a("h1",{id:"yuteleport-常见问题",tabindex:"-1"},[c("YuTeleport 常见问题 "),a("a",{class:"header-anchor",href:"#yuteleport-常见问题","aria-label":'Permalink to "YuTeleport 常见问题"'},"​")],-1)),a("div",h,[s(o,{page:""}),s(l,{page:""})]),e[1]||(e[1]=n(`<h2 id="旧-rtp-短命令还能用吗" tabindex="-1">旧 RTP 短命令还能用吗 <a class="header-anchor" href="#旧-rtp-短命令还能用吗" aria-label="Permalink to &quot;旧 RTP 短命令还能用吗&quot;">​</a></h2><p>最新版源码的主命令是 <code>/yuteleport</code>，默认别名是 <code>/ytp</code> 和 <code>/rtp</code>。文档、权限和 PlaceholderAPI 前缀都已经切换到 <code>yuteleport</code>。如果服务器还有依赖旧随机传送命令的菜单或脚本，建议改为 <code>/ytp</code> 或 <code>/yuteleport</code>。</p><h2 id="执行-rtp-后提示找不到安全传送点" tabindex="-1">执行 <code>/rtp</code> 后提示找不到安全传送点 <a class="header-anchor" href="#执行-rtp-后提示找不到安全传送点" aria-label="Permalink to &quot;执行 \`/rtp\` 后提示找不到安全传送点&quot;">​</a></h2><p>常见原因：</p><ul><li><code>teleports.rtp.worlds.default.radius</code> 范围内地形不可用。</li><li><code>height.min</code> 和 <code>height.max</code> 限制过窄。</li><li><code>allowed-materials</code> 或 <code>allowed-biomes</code> 白名单过于严格。</li><li><code>blocked-materials</code> 或 <code>blocked-biomes</code> 覆盖了大量候选点。</li><li><code>safety.max-attempts</code> 太低。</li><li>下界高度范围没有覆盖可站立洞穴。</li></ul><p>排查建议：</p><ol><li>临时开启 <code>debug: true</code>。</li><li>查看控制台拒绝原因。</li><li>放宽白名单或临时清空它。</li><li>提高 <code>max-attempts</code> 到 <code>64</code> 测试。</li><li>针对目标世界单独设置 <code>teleports.rtp.worlds.overrides.&lt;世界名&gt;</code>。</li></ol><h2 id="为什么玩家移动后传送取消" tabindex="-1">为什么玩家移动后传送取消 <a class="header-anchor" href="#为什么玩家移动后传送取消" aria-label="Permalink to &quot;为什么玩家移动后传送取消&quot;">​</a></h2><p>这是等待打断机制。默认会按 <code>teleports.defaults.cancel-triggers</code> 处理移动、受伤、交互、聊天和命令。视角转动不会取消，坐标方块变化才按移动处理。</p><p>如果希望立即传送：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">teleports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  defaults</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    warmup-seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span></code></pre></div><p>如果只想给特定玩家跳过等待，给予：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport.bypass.wait</span></span></code></pre></div><h2 id="back-会记录哪些位置" tabindex="-1"><code>/back</code> 会记录哪些位置 <a class="header-anchor" href="#back-会记录哪些位置" aria-label="Permalink to &quot;\`/back\` 会记录哪些位置&quot;">​</a></h2><p>默认会记录三类位置：</p><ul><li>YuTeleport 成功执行随机传送、warp、home、tpa、坐标分享或 back 前的位置。</li><li>玩家死亡位置。</li><li>其他插件或服务端命令触发传送前的位置。</li></ul><p>相关配置在 <code>teleports.back.capture</code>。如果 <code>/back</code> 提示没有可返回位置，优先检查 <code>teleports.back.enabled</code>、<code>capture.*</code> 开关、<code>include-types</code>、<code>min-distance</code>、<code>expire-seconds</code>，以及玩家是否拥有 <code>yuteleport.back.use</code> 和访问死亡点所需的 <code>yuteleport.back.death</code>。</p><p><code>/back list</code> 可查看可用历史；交互式聊天开启时，点击列表项会执行 <code>/back &lt;UUID&gt;</code> 返回指定条目。<code>persist: true</code> 时历史会保存在 <code>plugins/YuTeleport/data/back/</code>。</p><h2 id="开启经济后没有扣费" tabindex="-1">开启经济后没有扣费 <a class="header-anchor" href="#开启经济后没有扣费" aria-label="Permalink to &quot;开启经济后没有扣费&quot;">​</a></h2><p>请按顺序检查：</p><ol><li><code>economy.enabled</code> 是否为 <code>true</code>。</li><li><code>economy.provider</code> 是否与已安装插件一致，<code>vault</code> 需要 Vault 和经济插件，<code>playerpoints</code> 需要 PlayerPoints。</li><li>对应模块的 <code>cost</code> 是否大于 <code>0</code>。</li><li>命令执行者或付款方是否拥有 <code>yuteleport.bypass.cost</code>。</li><li>控制台是否提示经济服务未挂钩或扣费失败。</li></ol><p>扣费通常在目的地确认后进行。等待被取消、找不到安全点或事件取消时不会产生最终扣费，已扣款路径会按插件逻辑退款。</p><h2 id="控制台能不能执行-rtp" tabindex="-1">控制台能不能执行 <code>/rtp</code> <a class="header-anchor" href="#控制台能不能执行-rtp" aria-label="Permalink to &quot;控制台能不能执行 \`/rtp\`&quot;">​</a></h2><p>控制台不能执行无参数 <code>/rtp</code>、<code>/ytp</code> 或 <code>/yuteleport</code>，因为控制台没有当前世界和玩家位置。</p><p>控制台可以执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport &lt;玩家&gt;</span></span>
<span class="line"><span>yuteleport &lt;玩家&gt; &lt;世界&gt;</span></span>
<span class="line"><span>yuteleport reload</span></span></code></pre></div><h2 id="白名单和黑名单同时配置时谁优先" tabindex="-1">白名单和黑名单同时配置时谁优先 <a class="header-anchor" href="#白名单和黑名单同时配置时谁优先" aria-label="Permalink to &quot;白名单和黑名单同时配置时谁优先&quot;">​</a></h2><p>白名单优先。只要 <code>whitelist</code> 非空，插件就只允许白名单内世界传送，<code>blacklist</code> 会被忽略。</p><p>示例：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">world-access</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  blacklist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lobby</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  whitelist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">resource</span></span></code></pre></div><p>此时只有 <code>resource</code> 允许传送。</p><h2 id="玩家有权限但仍无法代传送其他人" tabindex="-1">玩家有权限但仍无法代传送其他人 <a class="header-anchor" href="#玩家有权限但仍无法代传送其他人" aria-label="Permalink to &quot;玩家有权限但仍无法代传送其他人&quot;">​</a></h2><p>代传送需要满足两个条件：</p><ol><li>命令执行者拥有 <code>yuteleport.teleport.others</code>。</li><li>目标玩家拥有 <code>yuteleport.use</code>。</li></ol><p>如果目标玩家没有 <code>yuteleport.use</code>，插件会返回权限不足。若目标玩家在冷却中，命令执行者需要 <code>yuteleport.bypass.cooldown.others</code> 或目标玩家拥有 <code>yuteleport.bypass.cooldown</code>。</p><h2 id="warp-或-home-数量权限不生效" tabindex="-1">warp 或 home 数量权限不生效 <a class="header-anchor" href="#warp-或-home-数量权限不生效" aria-label="Permalink to &quot;warp 或 home 数量权限不生效&quot;">​</a></h2><p>确认权限节点写法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport.warp.limit.25</span></span>
<span class="line"><span>yuteleport.home.limit.25</span></span>
<span class="line"><span>yuteleport.warp.limit.unlimited</span></span>
<span class="line"><span>yuteleport.home.limit.unlimited</span></span></code></pre></div><p>如果权限过期后数量超额，已有数据会保留，但超额项可能暂时不可用，玩家可删除或重新获得更高上限权限。</p><h2 id="placeholderapi-变量没有值" tabindex="-1">PlaceholderAPI 变量没有值 <a class="header-anchor" href="#placeholderapi-变量没有值" aria-label="Permalink to &quot;PlaceholderAPI 变量没有值&quot;">​</a></h2><p>依次确认：</p><ol><li>PlaceholderAPI 已安装并启用。</li><li><code>integrations.placeholderapi.enabled</code> 为 <code>true</code>。</li><li>安装或替换 PlaceholderAPI 后重启过服务器，或执行过 <code>/yuteleport reload</code>。</li><li>变量前缀是 <code>%yuteleport_*%</code>，不是旧随机传送插件前缀。</li></ol><p>测试：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/papi parse me %yuteleport_status%</span></span>
<span class="line"><span>/papi parse me %yuteleport_version%</span></span></code></pre></div><p>位置类变量在玩家尚无传送快照时返回空字符串，这是正常行为；未知变量返回 <code>null</code>。</p><h2 id="修改配置后需要重启吗" tabindex="-1">修改配置后需要重启吗 <a class="header-anchor" href="#修改配置后需要重启吗" aria-label="Permalink to &quot;修改配置后需要重启吗&quot;">​</a></h2><p>大多数配置可以通过以下命令重载：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/yuteleport reload</span></span></code></pre></div><p>重载会重新读取配置、语言文件、世界规则、经济挂钩、PlaceholderAPI 注册和模块命令。替换 jar、安装新依赖、修改服务端核心或排查模块命令注册问题时，建议重启服务器。</p><h2 id="folia-上需要额外配置吗" tabindex="-1">Folia 上需要额外配置吗 <a class="header-anchor" href="#folia-上需要额外配置吗" aria-label="Permalink to &quot;Folia 上需要额外配置吗&quot;">​</a></h2><p>不需要。插件声明 <code>folia-supported: true</code>，会在运行时检测 Folia 并使用 Global、Region 和 Entity Scheduler。其他插件通过 Java API 的 future 回调或事件操作实体、区块时，仍应按 Folia 规则调度到对应实体或区域。</p><h2 id="bstats-可以关闭吗" tabindex="-1">bStats 可以关闭吗 <a class="header-anchor" href="#bstats-可以关闭吗" aria-label="Permalink to &quot;bStats 可以关闭吗&quot;">​</a></h2><p>可以在服务器的 bStats 配置中关闭。关闭后不会影响随机传送、warp、home、tpa、back、坐标分享、冷却、扣费或世界规则。</p>`,53))])}const x=i(r,[["render",u]]);export{E as __pageData,x as default};
